-- 1086: Assembly Plastic Molding calculators -- the component loading and the multi-shot cycle as real database calculators.
--
-- GENERATED by scripts/generate-assembly-plastic-molding-calculators-migration.ts from
-- src/modules/bom-items/costing/plastic-molding/multi-shot/calculators/assembly-plastic-molding-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- Assembly Plastic Molding (multi-shot 2K/3K molding) was staged (reference data 2026-AssyPlastic; 97 USA HR Rates machines) but had no
-- cost engine: loading the pre-made components (Pick and Place) had no calculator, and nothing timed a multi-shot press, where every
-- station molds at once. Each shot is injection molding (migration 1087 links Multi-Shot Molding to the injection cycle-time calculator);
-- the multi-shot cycle is a helper the engine runs over the shots (the longest, then the tool index), which no operation maps to.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Assembly Plastic Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Assembly Plastic Molding - Component loading
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Assembly Plastic Molding - Component loading$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Assembly Plastic Molding - Component loading$q$, 'process', 'single', false, true, true, $q$Loading the pre-made components of a multi-shot part (Pick and Place: Manual Load / Robotic Load of each AssemblyComponentGcd) every shot: each component at tblComponentLoadTime for its weight and the load method, summed per shot; a manual load is slowed by handlingMultiplier and insertionMultiplier (memory/Assembly plastic molding variables), a robot is not.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Loading the pre-made components of a multi-shot part (Pick and Place: Manual Load / Robotic Load of each AssemblyComponentGcd) every shot: each component at tblComponentLoadTime for its weight and the load method, summed per shot; a manual load is slowed by handlingMultiplier and insertionMultiplier (memory/Assembly plastic molding variables), a robot is not.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Load Time$q$, $q$Load Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Manual Load$q$, $q$Manual Load$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Handling Multiplier$q$, $q$Handling Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Insertion Multiplier$q$, $q$Insertion Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Load Time} * ({Manual Load} * {Handling Multiplier} * {Insertion Multiplier} + 1 - {Manual Load}) * {Cycle Time Factor}$q$, 6, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Assembly Plastic Molding - Component loading$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Assembly Plastic Molding$q$ AND operation IN ($q$Pick and Place$q$);
END
$calc$;

-- Assembly Plastic Molding - Multi-shot cycle
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Assembly Plastic Molding - Multi-shot cycle$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Assembly Plastic Molding - Multi-shot cycle$q$, 'process', 'single', false, true, true, $q$The cycle of a multi-shot press (approved 2026-11-19: overlapped). Every station molds at once, each shot into its own stage, so the press waits for the longest shot (its fill, pack, cool and mold open/close by the injection cycle-time calculator with that shot's material); the components load at a station while the shots mold. Then the mold indexes (rotary table, rotating stack or core turn) for the press's tool index time (memory: toolIndexTime). A helper: no catalog operation maps to it.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The cycle of a multi-shot press (approved 2026-11-19: overlapped). Every station molds at once, each shot into its own stage, so the press waits for the longest shot (its fill, pack, cool and mold open/close by the injection cycle-time calculator with that shot's material); the components load at a station while the shots mold. Then the mold indexes (rotary table, rotating stack or core turn) for the press's tool index time (memory: toolIndexTime). A helper: no catalog operation maps to it.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Longest Shot Cycle$q$, $q$Longest Shot Cycle (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Load Time$q$, $q$Load Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Tool Index Time$q$, $q$Tool Index Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Shot Cycle$q$, $q$Shot Cycle (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$max({Longest Shot Cycle}, {Load Time}) + {Tool Index Time}$q$, 4, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Assembly Plastic Molding - Component loading$q$, 6, 1),
    ($q$Assembly Plastic Molding - Multi-shot cycle$q$, 4, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Assembly Plastic Molding$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1086: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
